132	/// Returns `true` if the `if` statement contains a comment
133	fn if_contains_comments(stmt: &StmtIf, checker: &Checker) -> bool {
134	    let source = checker.source();
135	
136	    // Use `line_end` (before the newline) instead of `full_line_end` (after
137	    // the newline) to avoid touching the range of a comment on the next line.
138	    // `TextRange::intersect` considers touching ranges as intersecting.
139	    let stmt_line_end = source.line_end(stmt.end());
140	    let check_range = TextRange::new(stmt.start(), stmt_line_end);
141	
142	    let Some(last_stmt) = stmt.body.last() else {
143	        return false;
144	    };
145	
146	    let stmt_full_end = source.full_line_end(stmt.end());
147	
148	    checker.comment_ranges().intersects(check_range)
149	        || if_has_trailing_comment(stmt, last_stmt, stmt_full_end, checker)
150	}
151	
152	/// Returns `true` if the `if` branch has a trailing own-line comment
153	fn if_has_trailing_comment(
154	    stmt: &StmtIf,
155	    last_body_stmt: &ruff_python_ast::Stmt,
156	    stmt_full_end: TextSize,
157	    checker: &Checker,
158	) -> bool {
159	    let (tokens, source) = (checker.tokens(), checker.source());
160	
161	    // Compare against the `if` keyword indentation rather than the body
162	    // statement — handles single-line forms like `if True: pass`
163	    let stmt_indentation = indentation(source, stmt).unwrap_or_default().text_len();
164	
165	    for token in tokens.after(stmt_full_end) {
166	        match token.kind() {
167	            TokenKind::Comment => {
168	                let comment_indentation =
169	                    comment_indentation_after(last_body_stmt.into(), token.range(), source);
170	
171	                match comment_indentation.cmp(&stmt_indentation) {
172	                    Ordering::Greater => return true,
173	                    Ordering::Equal | Ordering::Less => break,
174	                }
175	            }
176	
177	            TokenKind::NonLogicalNewline
178	            | TokenKind::Newline
179	            | TokenKind::Indent
180	            | TokenKind::Dedent => {}
181	
182	            _ => break,
183	        }
184	    }
185	
186	    false
187	}
